css:
body{margin:0;background:#eef1f4;padding:24px 12px}


/* Scoped to .spm-post so it will not clash with your builder theme.
   If your HTML block strips <style>, paste this into the page's Custom CSS. */
.spm-post{--ink:#16283d;--body:#33475b;--accent:#1d6fa5;--accent-dk:#155a86;
  --tint:#eef5fa;--muted:#6b7c8d;
  max-width:820px;margin:0 auto;padding:8px 20px 40px;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--body);line-height:1.72;font-size:17px;-webkit-font-smoothing:antialiased}
.spm-post *{box-sizing:border-box}
.spm-post h1{color:var(--ink);font-size:2.05rem;line-height:1.22;margin:.4em 0 .6em;letter-spacing:-.01em}
.spm-post h2{color:var(--ink);font-size:1.42rem;line-height:1.3;margin:2.1em 0 .6em;
  padding-bottom:.32em;border-bottom:2px solid var(--tint)}
.spm-post p{margin:0 0 1.15em}
.spm-post a{color:var(--accent);text-decoration:underline;text-underline-offset:2px;font-weight:600}
.spm-post a:hover{color:var(--accent-dk)}
.spm-hero{margin:0 0 1.6em}
.spm-hero img{width:100%;height:auto;display:block;border-radius:12px}
.spm-hero figcaption{font-size:.85rem;color:var(--muted);font-style:italic;margin-top:.6em;text-align:center}
@media(max-width:640px){
  .spm-post{font-size:16px;padding:8px 16px 32px}
  .spm-post h1{font-size:1.65rem}
  .spm-post h2{font-size:1.25rem}
}
